//! What the generator writes one output file into, and how that file names a type: by its path
//! in the same file, by `proto.wkt` for a well-known type, or through the module of another
//! generated file. Each output records the names it uses, so its imports list exactly those.
const std = @import("std");
const Features = @import("features.zig").Features;
const Allocator = std.mem.Allocator;
const names = @import("names.zig");
const index_file = @import("index.zig");
const Index = index_file.Index;

pub const Error = index_file.Error || error{NameCollision};

pub const Out = struct {
    arena: Allocator,
    bytes: std.ArrayList(u8) = .empty,
    index: *const Index,
    /// The .proto file whose declarations this output holds.
    file: []const u8,
    /// The features of the fields being written: the file's, then each enclosing message's.
    features: Features,
    /// The modules of other generated files this output names.
    used_modules: std.StringArrayHashMapUnmanaged(void) = .empty,
    /// Whether the output declares a service, which names `connect.Method`.
    uses_connect: bool = false,

    pub fn print(out: *Out, comptime format: []const u8, args: anytype) Allocator.Error!void {
        try out.bytes.print(out.arena, format, args);
    }

    pub fn indent(out: *Out, depth: usize) Allocator.Error!void {
        for (0..depth) |_| try out.bytes.appendSlice(out.arena, "    ");
    }

    /// The Zig expression this output names the type `type_name` with.
    pub fn reference(out: *Out, type_name: []const u8) Error![]const u8 {
        if (index_file.wkt_reference(type_name)) |short| return std.fmt.allocPrint(out.arena, "proto.wkt.{s}", .{short});
        const entry = try out.index.get(type_name);
        if (std.mem.eql(u8, entry.file, out.file)) {
            return entry.zig_path;
        }
        const module = try names.import_name(out.arena, entry.file);
        try out.used_modules.put(out.arena, module, {});
        return std.fmt.allocPrint(out.arena, "{s}.{s}", .{ module, entry.zig_path });
    }

    /// The file's text: its header, the imports its body uses, then the body.
    pub fn assemble(out: *const Out) Allocator.Error![]const u8 {
        var text: std.ArrayList(u8) = .empty;
        const arena = out.arena;
        try text.print(arena, "//! Code generated by protoc-gen-connect-zig. DO NOT EDIT.\n//! source: {s}\n", .{out.file});
        try text.print(arena, "//! The build gives this file the modules protobuf{s}", .{if (out.uses_connect) ", connect" else ""});
        for (out.used_modules.keys()) |module| try text.print(arena, ", {s}", .{module});
        try text.appendSlice(arena, ".\n");
        try text.appendSlice(arena, "const proto = @import(\"protobuf\");\n");
        if (out.uses_connect) try text.appendSlice(arena, "const connect = @import(\"connect\");\n");
        for (out.used_modules.keys()) |module| try text.print(arena, "const {s} = @import(\"{s}\");\n", .{ module, module });
        try text.appendSlice(arena, out.bytes.items);
        return text.items;
    }
};

/// A Zig name without its `@"..."` quoting.
pub fn unescaped(name: []const u8) []const u8 {
    const quote = "@\"";
    if (std.mem.startsWith(u8, name, quote)) return name[quote.len .. name.len - 1];
    return name;
}

pub fn full_name(arena: Allocator, scope: []const u8, name: []const u8) Allocator.Error![]const u8 {
    if (scope.len == 0) return name;
    return std.fmt.allocPrint(arena, "{s}.{s}", .{ scope, name });
}
